use vstd::prelude::*;

verus! {
    fn splitlines(a: Vec<String>, keepends: bool) -> Vec<Vec<String>>
        requires
            !a.is_empty(),
        ensures
            result.len() == a.len(),
            forall |i: usize| 0 <= i < a.len() ==> !result[i].is_empty(),
    {
        let mut result: Vec<Vec<String>> = Vec::new();
        let mut idx: usize = 0;

        while idx < a.len()
            invariant
                idx <= a.len(),
                result.len() == idx,
                forall |i: usize| 0 <= i < idx ==> !result[i].is_empty(),
        {
            let line = a[idx].clone(); // Get the current string
            let mut inner_list: Vec<String> = Vec::new();

            // Split the line based on line endings
            let parts = if keepends {
                line.split('\n').map(|s| s.to_string()).collect::<Vec<String>>()
            } else {
                line.split('\n').map(|s| s.trim_end().to_string()).collect::<Vec<String>>()
            };

            // Ensure that the inner list is non-empty
            assert(!parts.is_empty());
            inner_list.extend(parts);

            result.push(inner_list);
            idx += 1;
        }

        result
    }
}

